rules.message:
`ReactDOM.render` has been removed in React 19. Use `createRoot` instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (React 18 and earlier)
import ReactDOM from 'react-dom';
ReactDOM.render(<App />, document.getElementById('root'));

// ✅ AFTER (React 19)
import { createRoot } from 'react-dom/client';
const root = createRoot(document.getElementById('root')!);
root.render(<App />);
```
</details>

remediation.exampleAfter:
import { createRoot } from 'react-dom/client';
const root = createRoot(container);
root.render(<App />);

rules.message:
`ReactDOM.hydrate` has been removed in React 19. Use `hydrateRoot` from `'react-dom/client'` instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (React 18 and earlier)
import ReactDOM from 'react-dom';
ReactDOM.hydrate(<App />, document.getElementById('root'));

// ✅ AFTER (React 19)
import { hydrateRoot } from 'react-dom/client';
hydrateRoot(document.getElementById('root')!, <App />);
```
</details>

`ReactDOM.unmountComponentAtNode` has been removed in React 19. Use `root.unmount()` instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (React 18 and earlier)
import ReactDOM from 'react-dom';
ReactDOM.unmountComponentAtNode(container);

// ✅ AFTER (React 19)
root.unmount();
```
</details>

`ReactDOM.findDOMNode` has been removed in React 19. Use DOM `ref` instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
const node = ReactDOM.findDOMNode(this);

// ✅ AFTER
const nodeRef = useRef<HTMLDivElement>(null);
return <div ref={nodeRef} />;
```
</details>

`React.PropTypes` is removed in React 19. Use TypeScript types or the `prop-types` package.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
MyComponent.propTypes = {
  title: React.PropTypes.string
};

// ✅ AFTER
import PropTypes from 'prop-types';
MyComponent.propTypes = {
  title: PropTypes.string
};
```
</details>

String refs are removed in React 19. Use `useRef()` or callback refs.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
<input ref="nameInput" />

// ✅ AFTER
const inputRef = useRef<HTMLInputElement>(null);
<input ref={inputRef} />
```
</details>

`this.refs` has been removed in React 19. Use `React.createRef()` instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (React 18)
class Form extends React.Component {
  focus() { this.refs.input.focus(); }
  render() { return <input ref="input" />; }
}

// ✅ AFTER (React 19)
class Form extends React.Component {
  inputRef = React.createRef<HTMLInputElement>();
  focus() { this.inputRef.current?.focus(); }
  render() { return <input ref={this.inputRef} />; }
}
```
</details>

`defaultProps` on function components is removed in React 19. Use ES6 default parameter syntax.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
function Badge({ color }: { color?: string }) {
  return <span className={color} />;
}
Badge.defaultProps = { color: 'blue' };

// ✅ AFTER
function Badge({ color = 'blue' }: { color?: string }) {
  return <span className={color} />;
}
```
</details>

Legacy lifecycle methods like `componentWillReceiveProps` are removed in React 19.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
componentWillReceiveProps(nextProps) {
  this.setState({ count: nextProps.count });
}

// ✅ AFTER (componentDidUpdate or Hooks)
componentDidUpdate(prevProps) {
  if (prevProps.count !== this.props.count) {
    this.setState({ count: this.props.count });
  }
}
```
</details>

Legacy Context API (`contextTypes`) is removed in React 19. Migrate to `React.createContext()`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (Legacy Context)
class Child extends React.Component {
  static contextTypes = { theme: PropTypes.string };
}

// ✅ AFTER (Modern Context)
const ThemeContext = React.createContext('light');
function Child() {
  const theme = use(ThemeContext);
  return <div className={theme} />;
}
```
</details>

`React.createFactory` has been removed in React 19. Use standard JSX elements instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
const divFactory = React.createFactory('div');
return divFactory({ className: 'box' }, 'Hello');

// ✅ AFTER
return <div className="box">Hello</div>;
```
</details>

`react-test-renderer/shallow` is removed in React 19. Use `react-shallow-renderer` package instead.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
import ShallowRenderer from 'react-test-renderer/shallow';

// ✅ AFTER
import ShallowRenderer from 'react-shallow-renderer';
```
</details>

`react-dom/test-utils` is deprecated in React 19. Import `act` directly from `'react'`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
import { act } from 'react-dom/test-utils';

// ✅ AFTER
import { act } from 'react';
```
</details>

`useFormState` is deprecated in React 19. Use `useActionState` from `'react'`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
import { useFormState } from 'react-dom';
const [state, formAction] = useFormState(action, initialState);

// ✅ AFTER
import { useActionState } from 'react';
const [state, formAction, isPending] = useActionState(action, initialState);
```
</details>

`forwardRef` is deprecated in React 19. Function components now accept `ref` directly as a regular prop.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (React 18 wrapper)
const MyInput = forwardRef((props, ref) => {
  return <input ref={ref} {...props} />;
});

// ✅ AFTER (React 19 ref prop)
function MyInput({ ref, ...props }: { ref?: React.Ref<HTMLInputElement> }) {
  return <input ref={ref} {...props} />;
}
```
</details>

`<Context.Provider>` is deprecated in React 19. Render `<Context>` directly as a provider.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
const ThemeContext = createContext('light');
return (
  <ThemeContext.Provider value="dark">
    <App />
  </ThemeContext.Provider>
);

// ✅ AFTER (React 19)
const ThemeContext = createContext('light');
return (
  <ThemeContext value="dark">
    <App />
  </ThemeContext>
);
```
</details>

`useRef()` called with no arguments is deprecated in React 19 TypeScript definitions. Pass an initial value like `useRef(null)`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE (React 18)
const inputRef = useRef<HTMLInputElement>();

// ✅ AFTER (React 19)
const inputRef = useRef<HTMLInputElement>(null);
```
</details>

`react-test-renderer` is deprecated in React 19. Migrate component tests to `@testing-library/react`.

<details><summary><b>Before / After Example</b></summary>

```typescript
// ❌ BEFORE
import TestRenderer from 'react-test-renderer';
const renderer = TestRenderer.create(<MyComponent />);

// ✅ AFTER
import { render } from '@testing-library/react';
const { container } = render(<MyComponent />);
```
</details>
